const sharedWithMe = `-- name: SharedWithMe :many
SELECT n.id, n.slug, n.icon, n.color, s.level,
       COALESCE(t.name, tf.name, n.slug) AS name,
       COALESCE(u.display_name, '') AS owner_name
FROM node_shares s
JOIN nodes n ON n.id = s.node_id AND n.deleted_at IS NULL
LEFT JOIN users u ON u.id = n.owner_id
LEFT JOIN node_translations t  ON t.node_id = n.id AND t.lang = $1
LEFT JOIN node_translations tf ON tf.node_id = n.id AND tf.lang = 'en'
WHERE s.user_id = $2
ORDER BY s.created_at DESC
LIMIT $4 OFFSET $3
`

type SharedWithMeParams struct {
	Lang   string    `json:"lang"`
	UserID uuid.UUID `json:"user_id"`
	Off    int32     `json:"off"`
	Lim    int32     `json:"lim"`
}

type SharedWithMeRow struct {
	ID        int64      `json:"id"`
	Slug      string     `json:"slug"`
	Icon      string     `json:"icon"`
	Color     string     `json:"color"`
	Level     ShareLevel `json:"level"`
	Name      string     `json:"name"`
	OwnerName string     `json:"owner_name"`
}

// The branches somebody else has opened to this player: their own entry points into
// another player's tree.
func (q *Queries) SharedWithMe(ctx context.Context, arg SharedWithMeParams) ([]SharedWithMeRow, error) {
	rows, err := q.db.Query(ctx, sharedWithMe,
		arg.Lang,
		arg.UserID,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SharedWithMeRow{}
	for rows.Next() {
		var i SharedWithMeRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Icon,
			&i.Color,
			&i.Level,
			&i.Name,
			&i.OwnerName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

