const updateNode = `-- name: UpdateNode :one
UPDATE nodes SET
  node_type  = COALESCE($1, node_type),
  visibility = COALESCE($2, visibility),
  status     = COALESCE($3, status),
  slug       = COALESCE($4, slug),
  icon       = COALESCE($5, icon),
  color      = COALESCE($6, color),
  position   = COALESCE($7, position),
  updated_by = $8
WHERE id = $9 AND deleted_at IS NULL
RETURNING id, parent_id, root_id, path, depth, owner_id, extends_id, node_type, visibility, status, slug, icon, color, motif, position, metadata, created_by, updated_by, created_at, updated_at, deleted_at
`

type UpdateNodeParams struct {
	NodeType   pgtype.Text        `json:"node_type"`
	Visibility NullNodeVisibility `json:"visibility"`
	Status     NullNodeStatus     `json:"status"`
	Slug       pgtype.Text        `json:"slug"`
	Icon       pgtype.Text        `json:"icon"`
	Color      pgtype.Text        `json:"color"`
	Position   pgtype.Int4        `json:"position"`
	Actor      uuid.NullUUID      `json:"actor"`
	ID         int64              `json:"id"`
}

func (q *Queries) UpdateNode(ctx context.Context, arg UpdateNodeParams) (Node, error) {
	row := q.db.QueryRow(ctx, updateNode,
		arg.NodeType,
		arg.Visibility,
		arg.Status,
		arg.Slug,
		arg.Icon,
		arg.Color,
		arg.Position,
		arg.Actor,
		arg.ID,
	)
	var i Node
	err := row.Scan(
		&i.ID,
		&i.ParentID,
		&i.RootID,
		&i.Path,
		&i.Depth,
		&i.OwnerID,
		&i.ExtendsID,
		&i.NodeType,
		&i.Visibility,
		&i.Status,
		&i.Slug,
		&i.Icon,
		&i.Color,
		&i.Motif,
		&i.Position,
		&i.Metadata,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
